<?php require __DIR__.'/common.php'; $cfg=config();
$load=sys_getloadavg();$cores=1;if(is_readable('/proc/cpuinfo'))$cores=max(1,substr_count((string)file_get_contents('/proc/cpuinfo'),'processor\t:'));$cpu=isset($load[0])?round(min(100,$load[0]/$cores*100),1):null;
$mem=[];if(is_readable('/proc/meminfo')){foreach(file('/proc/meminfo') as $l){if(preg_match('/^(MemTotal|MemAvailable):\s+(\d+)/',$l,$m))$mem[$m[1]]=(int)$m[2];}}$total=$mem['MemTotal']??0;$avail=$mem['MemAvailable']??0;$used=max(0,$total-$avail);$disks=[];foreach(($cfg['disks']??['/']) as $mount){$t=@disk_total_space($mount);$f=@disk_free_space($mount);if($t)$disks[]=['mount'=>$mount,'used_gb'=>round(($t-$f)/1073741824,1),'total_gb'=>round($t/1073741824,1),'percent'=>round(($t-$f)/$t*100,1)];}
$uptime='';if(is_readable('/proc/uptime')){$s=(int)explode(' ',trim((string)file_get_contents('/proc/uptime')))[0];$uptime=floor($s/86400).'d '.floor(($s%86400)/3600).'h';}json_out(['cpu'=>$cpu,'cores'=>$cores,'ram'=>($total?round($used/$total*100,1):null),'ram_used_gb'=>round($used/1048576,1),'ram_total_gb'=>round($total/1048576,1),'disks'=>$disks,'uptime'=>$uptime]);